const staticData = $getWorkflowStaticData('global');
const item = $input.first();
const updateId = String(item.json.update_id);
const chatId = String(item.json.message?.chat?.id || '');

const key = `tg_${chatId}_${updateId}`;
if (staticData[key]) return [];
staticData[key] = Date.now();

const now = Date.now();
for (const k of Object.keys(staticData)) {
  if (k.startsWith('tg_') && now - staticData[k] > 10 * 60 * 1000) delete staticData[k];
}
return [item];
